(()=>{'use strict';
const MARK='__TAREFAS_ALPHA_2464_PATCH__';
if(globalThis[MARK])return;
globalThis[MARK]=true;
const LINKS=[
['Motorista PA','https://docs.google.com/spreadsheets/d/1T_BM9KY0NLwVhlifetQ6W6AdetujQjx--zOZHa27eQs/edit?usp=drivesdk'],
['Patrulheiro','https://docs.google.com/spreadsheets/d/1_LlfIHx4EuSHkC9BOR2VorvXoaiMyLa028wU6C0dQLs/edit?usp=drivesdk'],
['Permanência','https://docs.google.com/spreadsheets/d/13eEei_JdGjAdVo371BGfPS59QdYySe9lJ47DLjWb_x0/edit?usp=drivesdk']
];
function removeNext(){
 for(const e of document.querySelectorAll('#kNextServiceCard,#kNextService,.tm-next-service-kpi,[data-tarefas-next-service],[data-next-service],.next-service-card'))e.remove();
 for(const el of document.querySelectorAll('h1,h2,h3,h4,h5,h6,strong,b,p,span,button,a')){
  if(!el.children.length&&String(el.textContent||'').normalize('NFD').replace(/[̀-ͯ]/g,'').trim().toLowerCase()==='proximo servico'){
   const c=el.closest('.tm-next-service-kpi,#kNextServiceCard,#kNextService,.dashboard-card,.v4-card,.card,article,section');if(c)c.remove();
  }
 }
}
function openScales(){
 const old=document.getElementById('tmScales2464');if(old){old.remove();return}
 const wrap=document.createElement('div');wrap.id='tmScales2464';
 wrap.style.cssText='position:fixed;inset:0;z-index:2147483646;background:rgba(0,0,0,.58);display:flex;align-items:flex-end;justify-content:center;padding:12px';
 const box=document.createElement('div');box.style.cssText='width:min(560px,100%);max-height:82vh;overflow:auto;background:var(--v4-card,#101816);color:var(--v4-text,#fff);border:1px solid rgba(255,255,255,.12);border-radius:20px;padding:18px';
 box.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px"><strong style="font-size:20px">Escalas</strong><button type="button" data-close-scale style="border:0;background:transparent;color:inherit;font-size:24px">×</button></div><div data-scale-list style="display:grid;gap:8px"></div>';
 const list=box.querySelector('[data-scale-list]');
 for(const [label,url] of LINKS){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer external';a.textContent=label;a.style.cssText='display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 14px;border:1px solid rgba(255,255,255,.1);border-radius:12px;color:inherit;text-decoration:none;font-weight:800';const s=document.createElement('span');s.textContent='↗';s.style.opacity='.65';a.appendChild(s);list.appendChild(a)}
 wrap.appendChild(box);document.documentElement.appendChild(wrap);
 wrap.addEventListener('click',e=>{if(e.target===wrap||e.target.closest('[data-close-scale]'))wrap.remove()});
}
function removeExistingScales(){
 for(const el of document.querySelectorAll('a,button,[role="button"],li,span')){
  const t=String(el.textContent||'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if(t==='escalas' && el.dataset.tarefasScale2464!=='keep'){
   const item=el.closest('li,.nav-item,.menu-item,.tab-item,.hotbar-item,.drawer-item')||el;
   if(item)item.remove();
  }
 }
}
function wireServices(){
 removeExistingScales();
 for(const el of document.querySelectorAll('a,button,[role="button"],li,span,div')){
  const t=String(el.textContent||'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  if(t==='serviços e pessoal'||t==='servicos e pessoal'||t==='serviços'||t==='servicos'){
   const box=el.closest('li,.nav-item,.menu-item,.drawer-section,.menu-section,.hotbar-section')||el.parentElement;
   if(!box)continue;
   const a=document.createElement('a');a.href='#escalas';a.textContent='Escalas';a.dataset.tarefasScale2464='keep';a.style.cssText='cursor:pointer';
   a.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();openScales()},true);
   box.appendChild(a);
   break;
  }
 }
}
function wireLegacy(){
