  if(t==='pessoal / escalas'||t==='missões'||t==='missoes'){const item=el.closest('li,.nav-item,.menu-item,.tab-item')||el;if(item)item.remove()}
 }
 for(const el of document.querySelectorAll('a,button,[role="button"],[data-target],.nav-item,.tab-item')){
  const t=String(el.textContent||'').trim().normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase(),h=String(el.getAttribute?.('href')||'').toLowerCase();
  if((t==='escalas'||h==='#escalas')&&el.dataset.tarefasScale2464!=='keep'&&el.dataset.tarefasScale2464!=='1'){el.dataset.tarefasScale2464='1';el.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();openScales()},true)}
 }
}
function boot(){removeNext();wireLegacy();wireServices();let n=0;const tm=setInterval(()=>{removeNext();wireLegacy();wireServices();if(++n>120)clearInterval(tm)},250);window.addEventListener('focus',()=>{removeNext();wireLegacy();wireServices()});window.addEventListener('pageshow',()=>{removeNext();wireLegacy();wireServices()})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
